template <typename T>
struct has_foo {
    // SFINAE success case: requires T::foo to be valid
    template <typename C>
    static auto check(decltype(&C::foo)*) -> std::true_type;

    // Fallback: matches anything if SFINAE fails
    template <typename C>
    static auto check(...) -> std::false_type;

    static constexpr bool value = 
        decltype(check<T>(nullptr))::value;
};

struct TypeWithFoo { int foo = 0; };
struct TypeWithout {};

// Usage yields compile-time bool:
// has_foo<TypeWithFoo>::value; // true
// has_foo<TypeWithout>::value; // false
